// X-Hub-Signature-256 = "sha256=" + HMAC-SHA256(raw body, app secret). Must use the RAW bytes,
// hence the webhook's "Raw Body" option. A mismatch fails the run, so Workflow 0 logs it.
const crypto = require('crypto');
const secret = $env.WHATSAPP_APP_SECRET || '';
const item = $input.first();
const body = item.json.body ?? {};
if (!secret) return [{ json: { ...body, _signature: 'not checked: WHATSAPP_APP_SECRET is not set' } }];
const got = String(item.json.headers?.['x-hub-signature-256'] ?? '');
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const want = 'sha256=' + crypto.createHmac('sha256', secret).update(raw).digest('hex');
const ok = got.length === want.length && crypto.timingSafeEqual(Buffer.from(got), Buffer.from(want));
if (!ok) throw new Error('WhatsApp webhook signature mismatch');
return [{ json: { ...body, _signature: 'valid' } }];

// One item per inbound message. Status updates (sent/delivered/read) have no "messages" and are dropped.
const out = [];
for (const e of $json.entry ?? []) for (const ch of e.changes ?? []) {
  const v = ch.value ?? {};
  if (ch.field !== 'messages' || !Array.isArray(v.messages)) continue;
  const names = Object.fromEntries((v.contacts ?? []).map((k) => [k.wa_id, k.profile?.name]));
  for (const m of v.messages) {
    const text = m.type === 'text' ? m.text?.body
      : m.type === 'button' ? m.button?.text
      : m.type === 'interactive' ? (m.interactive?.button_reply?.title ?? m.interactive?.list_reply?.title)
      : null;
    out.push({ json: {
      source: 'whatsapp',
      contact: '+' + String(m.from).replace(/\D/g, ''),
      wa_id: m.from,
      contact_name: names[m.from] ?? null,
      message: text ?? `[${m.type} message]`,
      received_at: new Date(Number(m.timestamp) * 1000).toISOString(),
      external_id: m.id,
    } });
  }
}
return out;
